"""Render actual identity diagnostics and stored timing samples, without rerunning Java."""
from pathlib import Path
import csv
import hashlib
import html
import json
import statistics

ROOT = Path(__file__).resolve().parents[1]
def read(path): return (ROOT/path).read_text(encoding="utf-8").replace("\r\n", "\n")
def load(path): return json.loads(read(path))
def sha(path): return hashlib.sha256(read(path).encode()).hexdigest()
assets = []
def write(path, text):
    (ROOT/path).parent.mkdir(parents=True, exist_ok=True)
    (ROOT/path).write_text(text.replace("\r\n", "\n") + "\n", encoding="utf-8", newline="\n")
    assets.append(path)
replay = load("results/version-replay.json")
summary = load("results/summary.json")
changes = {change["version"]: change for change in replay["changes"]}
versions = {version["version"]: version for version in replay["inspection"]["versions"]}
nodes = {node["id"]: node for node in replay["inspection"]["nodes"]}
timings = list(csv.DictReader(read("results/timings.csv").splitlines()))
palette = {3: "#6a6760", 4: "#c05a2a", 5: "#247c70"}
def svg_start(title, desc, width, height):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">{html.escape(desc)}</desc><rect width="100%" height="100%" fill="#fffaf1"/><g font-family="ui-monospace,monospace" fill="#27251f">'

# Every rendered ID and edge is taken from the shared inspection snapshot.
root_ids = [versions[v]["root"] for v in [3, 4, 5]]
leaves = sorted({child for root in root_ids for child in nodes[root]["children"]})
positions = {root: (180 + i*365, 80) for i, root in enumerate(root_ids)}
positions.update({node: (110 + i*215, 280) for i, node in enumerate(leaves)})
elements = [svg_start("Three version roots sharing actual trie nodes", "Versions3,4,5 have distinct roots; common leaf IDs are one physical node identity each. The updated beta leaf is separate.", 1120, 385)]
for version, root in zip([3, 4, 5], root_ids):
    x,y=positions[root]
    for child in nodes[root]["children"]:
        cx,cy=positions[child]
        elements.append(f'<path d="M{x} {y+32} C{x} 170 {cx} 185 {cx} {cy-28}" stroke="{palette[version]}" stroke-width="2" fill="none" opacity=".75"/>')
for version, root in zip([3,4,5],root_ids):
    x,y=positions[root]
    elements.append(f'<rect x="{x-95}" y="{y-32}" width="190" height="64" rx="3" fill="#fff" stroke="{palette[version]}" stroke-width="2"/><text x="{x}" y="{y-5}" text-anchor="middle" font-size="17">v{version} → node #{root}</text><text x="{x}" y="{y+18}" text-anchor="middle" font-size="11">bitmap {nodes[root]["bitmapHex"]}</text>')
for leaf in leaves:
    x,y=positions[leaf]; entry=nodes[leaf]["entries"][0]
    elements.append(f'<rect x="{x-85}" y="{y-28}" width="170" height="60" fill="#fff" stroke="#9c9689"/><text x="{x}" y="{y-4}" text-anchor="middle" font-size="15">{entry["key"]} = {entry["value"]}</text><text x="{x}" y="{y+18}" text-anchor="middle" font-size="12">identity #{leaf}</text>')
elements.append('<text x="35" y="365" font-size="12" fill="#6a6760">Colors identify version roots; each leaf box represents one shared object identity, not a copied value.</text></g></svg>')
write("docs/figures/shared-trie.svg", "".join(elements))

pos={0:(70,210),1:(205,210),2:(340,210),3:(475,210),4:(690,65),5:(690,165),7:(690,265),8:(690,365),6:(970,65)}
labels={1:"alpha=1",2:"beta=2",3:"gamma=3",4:"beta=20",5:"delta=4",6:"remove alpha",7:"remove absent",8:"beta=2 again"}
parts=[svg_start("Branching immutable version history", "The trace forks from version3. Versions7 and8 are no-ops retaining the exact root; version6 descends from version4.",1120,435)]
for v in pos:
    if v==0: continue
    parent=changes[v]["parent"]; x,y=pos[parent]; cx,cy=pos[v]
    parts.append(f'<path d="M{x+31} {y} L{cx-31} {cy}" stroke="#a39a8b" stroke-width="2" fill="none"/>')
for v,(x,y) in pos.items():
    color="#247c70" if v in [7,8] else "#c05a2a" if v in [4,6] else "#27251f"
    parts.append(f'<circle cx="{x}" cy="{y}" r="28" fill="#fff" stroke="{color}" stroke-width="2"/><text x="{x}" y="{y+6}" text-anchor="middle" font-size="17">v{v}</text><text x="{x}" y="{y+48}" text-anchor="middle" font-size="11">{labels.get(v,"empty")}</text>')
parts.append('</g></svg>');write("docs/figures/version-branches.svg","".join(parts))

def scroll(label,content): return f'<div class="scroll" tabindex="0" role="region" aria-label="{html.escape(label)}">{content}</div>'
def plot(file,alt): return scroll(alt+"; horizontally scrollable",f'<img class="diagram" src="figures/{file}" alt="{html.escape(alt)}">')
sharing_rows="".join(f'<tr><td>v{v}</td><td>v{changes[v]["parent"]}</td><td>{changes[v]["stats"]["nodes"]}</td><td class="shared">{changes[v]["sharing"]["sharedNodes"]}</td><td>{changes[v]["sharing"]["newNodes"]}</td><td>{str(changes[v]["sharing"]["sameRoot"]).lower()}</td></tr>' for v in [3,4,5,6,7,8])
collision_rows="".join(f'<tr><td>v{v}</td><td>{changes[v]["stats"]["size"]}</td><td>{changes[v]["stats"]["branches"]}</td><td>{changes[v]["stats"]["collisions"]}</td><td>{changes[v]["stats"]["leaves"]}</td><td>{changes[v]["stats"]["maxDepth"]}</td></tr>' for v in [9,10,12,13,14,15,17,18,19,20])
timing_rows=[]
for workload in summary["workloads"]:
    for phase in ["retained-updates","base-reads"]:
        values={impl:[int(row["elapsed_nanos"])/1e6 for row in timings if row["workload"]==workload["workload"] and row["phase"]==phase and row["implementation"]==impl] for impl in ["hamt","copy-hashmap"]}
        timing_rows.append(f'<tr><td>{workload["workload"]}</td><td>{phase}</td>'+"".join(f'<td class="num">{statistics.median(values[impl]):.3f}</td><td class="num small">{min(values[impl]):.3f}–{max(values[impl]):.3f}</td>' for impl in ["hamt","copy-hashmap"])+"</tr>")
nodes_rows="".join(f'<tr><td>{row["workload"]}</td><td>{row["retainedVersions"]}</td><td class="shared">{row["distinctHamtNodes"]:,}</td><td>{row["sumPerVersionHamtNodes"]:,}</td><td>{row["baselineRetainedEntryReferences"]:,}</td></tr>' for row in summary["workloads"])
document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Persistent HAMT map</title><style>
:root{{--paper:#fffaf1;--ink:#27251f;--muted:#726b60;--line:#ddd3c3;--accent:#c05a2a;--green:#247c70}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth;scroll-padding-top:20px}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}}a{{color:var(--green);text-underline-offset:4px}}a:focus-visible,.scroll:focus-visible{{outline:3px solid var(--accent);outline-offset:4px}}header{{max-width:1210px;margin:auto;padding:22px 30px;display:flex;justify-content:space-between;gap:24px;border-bottom:1px solid var(--line);font:12px/1.5 ui-monospace,monospace}}nav{{display:flex;flex-wrap:wrap;gap:20px}}main{{max-width:1210px;margin:auto;padding:0 30px}}section{{padding:58px 0;border-bottom:1px solid var(--line)}}h1{{font-size:clamp(43px,6vw,78px);line-height:1.06;letter-spacing:-.055em;font-weight:580;margin:20px 0 28px}}h2{{font-size:clamp(28px,3.4vw,40px);line-height:1.18;letter-spacing:-.035em;font-weight:580;margin:12px 0 24px}}h3{{font-size:18px;margin:0 0 14px}}p{{max-width:880px;margin:0 0 18px}}.lead{{font-size:20px;line-height:1.6;max-width:850px}}.label,.mono{{font-family:ui-monospace,Consolas,monospace}}.label{{font-size:12px;color:var(--muted);letter-spacing:.07em}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin:32px 0 0;padding-top:26px;border-top:1px solid var(--line)}}.stats strong{{font:38px/1.25 ui-monospace,monospace;display:block}}.stats span{{font-size:13px;color:var(--muted)}}.scroll{{max-width:100%;overflow:auto;margin:24px 0}}.diagram{{display:block;width:100%;min-width:780px;height:auto}}table{{border-collapse:collapse;width:100%;white-space:nowrap;font-size:13px}}th,td{{text-align:left;padding:12px 15px;border-bottom:1px solid var(--line)}}th{{color:var(--muted);font-weight:500;font-size:12px}}td.num{{text-align:right;font-family:ui-monospace,monospace}}.small,.note{{font-size:13px;color:var(--muted)}}.shared{{color:var(--green);font-weight:650}}.split{{display:grid;grid-template-columns:1fr 1fr;gap:40px}}.panel{{padding:24px;background:#f3ecdf;border-top:3px solid var(--accent)}}.formula{{font:18px/1.85 ui-monospace,monospace;margin:18px 0}}.code{{background:#292820;color:#f5eddb;padding:26px;font:14px/1.8 ui-monospace,monospace;overflow:auto}}code{{font:13px/1.7 ui-monospace,monospace;overflow-wrap:anywhere}}.links{{display:flex;flex-wrap:wrap;gap:12px 25px;margin:24px 0}}.limit{{border-left:3px solid var(--accent);padding-left:20px}}footer{{max-width:1210px;margin:auto;padding:30px;font-size:12px;color:var(--muted)}}@media(max-width:700px){{header{{display:block;padding:18px 20px}}nav{{margin-top:14px;gap:12px 18px}}main{{padding:0 20px}}section{{padding:40px 0}}.stats{{grid-template-columns:1fr 1fr;gap:20px}}.stats strong{{font-size:32px}}.lead{{font-size:18px}}.split{{display:block}}.panel{{margin-top:20px;padding:20px}}.links{{display:block}}.links a{{display:block;margin:9px 0}}th,td{{padding:11px}}.code{{font-size:12px;padding:18px}}.formula{{font-size:15px}}}}@media(prefers-reduced-motion:reduce){{html{{scroll-behavior:auto}}}}
</style></head><body><header><span>JAVA 21 / IMMUTABLE DATA STRUCTURES</span><nav aria-label="Report sections"><a href="#versions">Versions</a><a href="#sharing">Trie identities</a><a href="#collisions">Collisions</a><a href="#measurements">Measurements</a><a href="#reproduction">Evidence</a></nav></header><main>
<section id="overview"><div class="label">01 / PERSISTENT MAP IMPLEMENTATION</div><h1>Persistent HAMT map</h1><p class="lead">An immutable hash-array-mapped trie for String keys and bounded integer values. Updates copy one path; historical roots remain readable and can branch into new versions.</p><div class="stats"><div><strong>23</strong><span>recorded fork/update operations</span></div><div><strong>24</strong><span>retained trace versions</span></div><div><strong>88,560</strong><span>seeded historical oracle checks</span></div><div><strong>7</strong><span>maximum hash-branch depth</span></div></div><p class="note" style="margin-top:24px">Actual Java node identities establish structural sharing. This study does not estimate JVM object sizes or claim physical memory savings.</p></section>
<section id="versions"><div class="label">02 / BRANCHING HISTORY</div><h2>Updates preserve their parent versions</h2><p>Version 3 contains alpha=1, beta=2, gamma=3. One branch changes beta; another adds delta. An absent removal and an equal-value replacement return the same map object and root.</p>{plot("version-branches.svg","Actual parent relationships for the first eight trace operations")}<p class="note">v4 retains beta=20 while v3 and v5 retain beta=2. Every saved version is checked again after each subsequent trace operation. Green no-op versions reuse root #3.</p><div class="links"><a href="../data/version-trace.csv">Original parent/operation trace</a><a href="../results/version-replay.json">Every immutable snapshot</a></div></section>
<section id="sharing"><div class="label">03 / NODE IDENTITY INSPECTION</div><h2>Shared subtrees are the same objects</h2><p>These three actual roots point into one identity-indexed graph. Updating beta replaces its leaf and the root; alpha and gamma keep their original identities. A new branch can reuse beta's earlier leaf.</p>{plot("shared-trie.svg","Version3,4,5 roots pointing to actual shared and replaced leaves")}{scroll("Exact per-version node sharing counts",f'<table><thead><tr><th>Version</th><th>Parent</th><th>Reachable nodes</th><th>Shared with parent</th><th>New reachable nodes</th><th>Same root</th></tr></thead><tbody>{sharing_rows}</tbody></table>')}<div class="split"><div><h3>Bitmap-indexed branches</h3><div class="formula">slot = (hash &gt;&gt;&gt; shift) &amp; 31<br>bit = 1 &lt;&lt; slot<br>index = bitCount(bitmap &amp; (bit − 1))</div><p class="note">Packed children contain only occupied slots. Five hash bits are consumed at each level; the last level uses the remaining two bits.</p></div><div><h3>Identity accounting</h3><p class="note">IdentityHashMap-backed sets measure shared/new/retired nodes. “Retired” means absent from the child version; an older root may still retain that object. Node IDs are deterministic inspection labels, not heap addresses.</p></div></div></section>
<section id="collisions"><div class="label">04 / HASH AND DELETION EDGE CASES</div><h2>Full-hash collisions stay explicit</h2><div class="split"><article class="panel"><h3>Equal hashes, unequal keys</h3><div class="formula">hash("Aa") = hash("BB")<br>= 0x00000840</div><p>A collision node retains both distinct String keys. Lookup compares the whole key. Replacing or removing one entry leaves the other value intact.</p><p class="note">The collision workload includes 64 different Aa/BB-family keys with the same complete 32-bit hash. Collision scanning remains linear in that bucket.</p></article><article class="panel"><h3>Deep shared prefixes</h3><div class="formula">0x00000001<br>0x40000001<br>0x80000001</div><p>These generated String hashes share 30 low bits. They exercise all seven levels, including a negative signed hash.</p><p class="note">A sole terminal can move up after deletion. A sole branch must retain its level; promoting it would skip a hash chunk and break lookup.</p></article></div>{scroll("Collision expansion and deep-prefix contraction counts",f'<table><thead><tr><th>Version</th><th>Entries</th><th>Branches</th><th>Collision nodes</th><th>Leaves</th><th>Maximum depth</th></tr></thead><tbody>{collision_rows}</tbody></table>')}<p class="note">v10 is the Aa/BB collision. v12 adds a different hash; v13 removes it and restores the collision root. v18 contains all three deep-prefix keys; v20 compresses to a single leaf after two removals.</p></section>
<section id="measurements"><div class="label">05 / RETAINED VERSION WORKLOADS</div><h2>Counts and local timings measure different things</h2><p>Each workload applies 200 operations while retaining 201 versions, then measures a separate batch of 4,096 reads from its initial map. The baseline copies a Java HashMap for every update and keeps each copy read-only afterward.</p>{scroll("Logical sharing counts across201 retained versions",f'<table><thead><tr><th>Workload</th><th>Versions</th><th>Distinct HAMT nodes</th><th>Sum of version-node counts</th><th>Baseline entry references</th></tr></thead><tbody>{nodes_rows}</tbody></table>')}<p class="note">These are different logical units. Repeated reachability, entry references, arrays, entries and map wrappers are not interchangeable JVM byte measurements. Arrays and entry objects are not included in the node count.</p>{scroll("Seven timing repetitions summarized as medians and ranges",'<table><thead><tr><th>Workload</th><th>Phase</th><th>HAMT median ms</th><th>HAMT min–max</th><th>Copy baseline median ms</th><th>Baseline min–max</th></tr></thead><tbody>'+"".join(timing_rows)+'</tbody></table>')}<p class="note">Two warm-ups, seven measured repetitions, alternating implementation order. Retained lists escape through a volatile reference; checksums are consumed. Setup and full correctness checks are outside timing. GC/JIT/system noise remain uncontrolled; this is not JMH or a general production speedup claim.</p><p class="limit">The baseline copies even on absent deletes. HAMT can return the same instance for a no-op. This compares the stated full-copy version strategy, not the best possible JDK implementation or another persistent-map library.</p></section>
<section id="reproduction"><div class="label">06 / REPLAY AND VERIFICATION</div><h2>Inspect all versions and rerun the workloads</h2><pre class="code">java tools/Run.java test
java tools/Run.java replay data/version-trace.csv
java tools/Run.java measure results-local</pre><p>The map implementation contains leaves, collision arrays and bitmap-indexed branches; it does not wrap a HashMap. Independently copied HashMaps serve as test/replay oracles and the explicit benchmark baseline.</p><p class="note">Contract: no null keys; well-formed UTF-16 keys up to128 code units; integer values −1,000,000 through1,000,000; up to16,384 entries per map. Empty keys, Unicode, negative hash codes and bitmap slot31 are covered. No custom equality, hash mixing, concurrent mutation, transient builder or physical-memory instrumentation is supplied.</p><div class="links"><a href="../README.md">Design and commands</a><a href="implementation.md">Trie invariants and benchmark scope</a><a href="../results/version-sharing.csv">Raw identity counts</a><a href="../data/benchmark-operations.csv">Every benchmark operation/read</a><a href="../results/timings.csv">84 raw timing rows</a><a href="../results/environment.json">Environment and source hashes</a><a href="screenshots/README.md">Screenshots</a><a href="recordings/README.md">Review recording</a></div><p class="note">Primary reference: Phil Bagwell, <a href="https://lampwww.epfl.ch/papers/idealhashtrees.pdf">Ideal Hash Trees</a> (2001). This implementation applies bitmap-indexed hash chunks and immutable path copying; it does not reproduce the paper's system or performance measurements.</p><p class="note">AI-assisted implementation and owned synthetic traces. Counts and timings come from actual JVM executions. Captures show inspection of the report, not historical manual work or production deployment.</p></section></main><footer>PERSISTENT HAMT MAP · <a href="figures/artifacts.sha256">LF-normalized presentation provenance</a></footer></body></html>'''
document=document.replace('up to128','up to 128').replace('through1,000,000','through 1,000,000').replace('up to16,384','up to 16,384').replace('slot31','slot 31').replace('across201','across 201')
write("docs/report.html",document)
assets += ["presentation/render.py","results/summary.json","results/version-replay.json","results/timings.csv"]
(ROOT/"docs/figures/artifacts.sha256").write_text("\n".join(f"{sha(path)}  {path}" for path in sorted(assets))+"\n",encoding="utf-8",newline="\n")
print("Rendered six sections from preserved identity/count/timing evidence.")
